    q = {"id": id, "type": "multiple_choice", "level": level, "prompt": prompt, "options": options, "answer": answer}
    if explanation: q["explanation"] = explanation
    if promptFr: q["promptFr"] = promptFr
    if audioText: q["audioText"] = audioText
    return q

