            _q("tef-v1-6", "B1", "Complétez : « Si j'avais le temps, je ___ au sport plus souvent. »", ["jouerais", "joue", "jouerai", "jouais"], 0, "Hypothèse présente (si + imparfait) → conditionnel présent : \"je jouerais\".", "Complétez la phrase.", ""),
            _q("tef-v1-7", "B1", "Complétez : « Le train est parti ___ l'heure. »", ["à", "en", "dans", "par"], 0, "On dit \"à l'heure\" (ponctuel). \"En avance/en retard\" utilisent \"en\".", "Complétez la phrase.", ""),
            _q("tef-v1-8", "B1", "Complétez : « La fille ___ tu as parlé est ma cousine. »", ["que", "qui", "dont", "où"], 2, "Verbe \"parler de\" : on utilise \"dont\" (la fille dont tu as parlé).", "Complétez la phrase.", ""),
            _q("tef-v1-9", "B1", "Complétez : « Bien qu'il ___ fatigué, il est venu travailler. »", ["est", "soit", "était", "sera"], 1, "Après \"bien que\", on emploie le subjonctif : \"bien qu'il soit\".", "Complétez la phrase.", ""),
