            _q("tef-v1-12", "B2", "Complétez : « Cette région est connue ___ ses vins. »", ["pour", "de", "par", "avec"], 0, "\"Être connu pour\" = célèbre pour. La préposition correcte est \"pour\".", "Complétez la phrase.", ""),
