            _q("tef-v2-8", "B1", "Complétez : « La maison ___ je rêve est en bord de mer. »", ["que", "qui", "dont", "où"], 2, "Verbe \"rêver de\" : on utilise \"dont\" (la maison dont je rêve).", "Complétez la phrase.", ""),
