            _q("tef-v2-11", "B2", "Complétez : « S'il faisait beau, on ___ pique-niquer. »", ["pourrait", "pourra", "aurait pu", "peut"], 0, "Hypothèse présente (si + imparfait) → conditionnel présent : \"on pourrait\".", "Complétez la phrase.", ""),
